  ('dragon-egg', '{"en":"The Missing Dragon Egg","ar":"بيضة التنين المفقودة"}'::jsonb, '{"en":"Help Mama Dragon find her egg.","ar":"ساعد أم التنين في إيجاد بيضتها."}'::jsonb, null, array['magic-castle']::text[], true, null, 'published'),
  ('space-signal', '{"en":"The Space Signal","ar":"إشارة الفضاء"}'::jsonb, '{"en":"A mysterious signal from the stars.","ar":"إشارة غامضة من النجوم."}'::jsonb, null, array['space-world']::text[], true, null, 'published'),
  ('dino-map', '{"en":"The Dinosaur Map","ar":"خريطة الديناصورات"}'::jsonb, '{"en":"Follow the map to the dinosaur nests.","ar":"اتبع الخريطة إلى أعشاش الديناصورات."}'::jsonb, null, array['dinosaur-island']::text[], true, null, 'published'),
  ('castle-room', '{"en":"The Secret Castle Room","ar":"غرفة القلعة السرية"}'::jsonb, '{"en":"A hidden room behind a painting.","ar":"غرفة مخفية خلف لوحة."}'::jsonb, null, array['magic-castle']::text[], true, null, 'published'),
  ('underwater-city', '{"en":"The Underwater City","ar":"المدينة تحت الماء"}'::jsonb, '{"en":"Dive into a sparkling sunken city.","ar":"اغطس في مدينة غارقة متلألئة."}'::jsonb, null, array['underwater-world']::text[], true, null, 'published'),
  ('first-friends', '{"en":"Mimo’s First Friends","ar":"أصدقاء ميمو الأوائل"}'::jsonb, '{"en":"A gentle first season for Little Explorers: say hello, find colours, meet animals.","ar":"موسم أول لطيف للمستكشفين الصغار."}'::jsonb, 1, array['my-home','playground-park','animal-forest','music-valley','supermarket-city','beach-island']::text[], false, null, 'published'),
  ('clocktower-code', '{"en":"The Clocktower Code","ar":"شفرة برج الساعة"}'::jsonb, '{"en":"A mystery season for Heroes: read clues, build sentences, question suspects.","ar":"موسم غامض للأبطال: اقرأ الأدلة وابنِ الجمل واستجوب المشتبه بهم."}'::jsonb, 1, array['school-town','supermarket-city','playground-park','animal-forest','beach-island','airport-adventures','magic-castle']::text[], false, null, 'published'),
  ('winter-wonder', '{"en":"Winter Wonder","ar":"عجائب الشتاء"}'::jsonb, '{"en":"A seasonal snowy adventure.","ar":"مغامرة شتوية موسمية."}'::jsonb, null, array['nature-mountain']::text[], false, 'winter', 'published')
insert into journeys (id, arc_id, sort_order, world_id, title, summary, topics, cliffhanger, reward_ids, min_stage, memory_key, status, version) values
  ('gk-01', 'golden-key', 1, 'my-home', '{"en":"The Key from the Sky","ar":"المفتاح الذي سقط من السماء"}'::jsonb, '{"en":"A golden key falls into the garden — and Mimo’s egg starts to glow.","ar":"مفتاح ذهبي يسقط في الحديقة، وبيضة ميمو تبدأ بالتوهج."}'::jsonb, array['greetings','colors','home']::text[], '[{"speaker":"narrator","text":{"en":"That night, the key glows… and points towards the window.","ar":"في تلك الليلة، يتوهج المفتاح… ويشير نحو النافذة."},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.key']::text[], 1, 'found-golden-key', 'published', 1),
  ('gk-02', 'golden-key', 2, 'my-home', '{"en":"Who Dropped the Key?","ar":"من أسقط المفتاح؟"}'::jsonb, '{"en":"Lumi and Zuzu search the house for clues.","ar":"لومي وزوزو يبحثان في البيت عن أدلة."}'::jsonb, array['home','family','colors']::text[], '[{"speaker":"narrator","text":{"en":"Something giggles behind the slide…","ar":"شيء ما يضحك خلف الزحليقة…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.footprint','furniture.lamp']::text[], 1, null, 'published', 1),
  ('gk-03', 'golden-key', 3, 'playground-park', '{"en":"Footprints in the Park","ar":"آثار في الحديقة"}'::jsonb, '{"en":"The footprints lead through the playground. Who made them?","ar":"الآثار تقود عبر الملعب. من صنعها؟"}'::jsonb, array['toys','actions','numbers']::text[], '[{"speaker":"narrator","text":{"en":"A school bell rings far away… DING DONG!","ar":"جرس مدرسة يرن من بعيد… دينغ دونغ!"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.music','clothing.cap']::text[], 1, null, 'published', 1),
  ('gk-04', 'golden-key', 4, 'school-town', '{"en":"Professor Pico’s Clue","ar":"دليل البروفيسور بيكو"}'::jsonb, '{"en":"At School Town, Pico finds a drawing of the key’s door.","ar":"في مدينة المدرسة، يجد بيكو رسمة لباب المفتاح."}'::jsonb, array['school','colors','numbers']::text[], '[{"speaker":"narrator","text":{"en":"Zuzu’s tummy rumbles… and the key smells of cookies?","ar":"بطن زوزو يقرقر… والمفتاح رائحته كالكعك؟"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.owl','furniture.bookshelf']::text[], 1, null, 'published', 1),
  ('gk-05', 'golden-key', 5, 'supermarket-city', '{"en":"The Key-Shaped Cookie","ar":"الكعكة على شكل مفتاح"}'::jsonb, '{"en":"A baker in Supermarket City made cookies shaped like the key!","ar":"خبّاز في مدينة السوبرماركت صنع كعكًا على شكل المفتاح!"}'::jsonb, array['food','numbers','shopping']::text[], '[{"speaker":"narrator","text":{"en":"Deep in the forest, two big eyes open in the dark…","ar":"في عمق الغابة، تنفتح عينان كبيرتان في الظلام…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.cookie']::text[], 1, null, 'published', 1),
  ('gk-06', 'golden-key', 6, 'animal-forest', '{"en":"The Owl Who Saw Everything","ar":"البومة التي رأت كل شيء"}'::jsonb, '{"en":"A wise owl will help — if you can answer her animal riddles.","ar":"بومة حكيمة ستساعد إن استطعت حل ألغاز الحيوانات."}'::jsonb, array['animals','nature']::text[], '[{"speaker":"narrator","text":{"en":"Woof… woof… a tiny, sad bark comes from the river.","ar":"هاو… هاو… نباح صغير وحزين يأتي من النهر."},"emotion":"worried"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.owl','item.lantern']::text[], 1, null, 'published', 1),
  ('gk-07', 'golden-key', 7, 'animal-forest', '{"en":"The Lost Puppy","ar":"الجرو الضائع"}'::jsonb, '{"en":"A puppy is lost by the river. Can you help him get home?","ar":"جرو ضائع عند النهر. هل يمكنك مساعدته على العودة؟"}'::jsonb, array['animals','descriptions','colors']::text[], '[{"speaker":"narrator","text":{"en":"Far away, a seashell starts to sing…","ar":"بعيدًا، تبدأ صدفة بالغناء…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.puppy','item.map']::text[], 1, 'helped-puppy', 'published', 1),
  ('gk-08', 'golden-key', 8, 'beach-island', '{"en":"Message in a Shell","ar":"رسالة في صدفة"}'::jsonb, '{"en":"A singing shell holds the next clue — but a storm is coming.","ar":"صدفة مغنية تحمل الدليل التالي، لكن عاصفة قادمة."}'::jsonb, array['nature','weather','clothing']::text[], '[{"speaker":"narrator","text":{"en":"A plane with golden wings is waiting at Gate 7…","ar":"طائرة بأجنحة ذهبية تنتظر عند البوابة ٧…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.shell','furniture.plant']::text[], 2, null, 'published', 1),
  ('gk-09', 'golden-key', 9, 'airport-adventures', '{"en":"Tickets to the Clouds","ar":"تذاكر إلى السحاب"}'::jsonb, '{"en":"Find your way through the airport to the golden plane.","ar":"جد طريقك عبر المطار إلى الطائرة الذهبية."}'::jsonb, array['travel','transport','directions']::text[], '[{"speaker":"narrator","text":{"en":"The castle has a hundred doors. Ninety-nine are fake…","ar":"للقلعة مئة باب. تسعة وتسعون منها مزيفة…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.cloud','item.compass']::text[], 2, null, 'published', 1),
  ('gk-10', 'golden-key', 10, 'magic-castle', '{"en":"The Castle of a Hundred Doors","ar":"قلعة المئة باب"}'::jsonb, '{"en":"Explore the Hall of Doors. Only describing words open them.","ar":"استكشف قاعة الأبواب. فقط كلمات الوصف تفتحها."}'::jsonb, array['adventure','home','descriptions']::text[], '[{"speaker":"zuzu","text":{"en":"Leave it to me! I’ll open one… right now!","ar":"اتركوه لي! سأفتح واحدًا… الآن!"},"emotion":"silly"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.crown','clothing.crown']::text[], 2, null, 'published', 1),
  ('gk-11', 'golden-key', 11, 'magic-castle', '{"en":"Zuzu Opens the Wrong Door","ar":"زوزو يفتح الباب الخطأ"}'::jsonb, '{"en":"Oops! Zuzu’s door is full of bouncing balloons. Fix the mix-up!","ar":"أوبس! باب زوزو مليء بالبالونات القافزة. أصلح الخلط!"}'::jsonb, array['descriptions','colors','adventure']::text[], '[{"speaker":"narrator","text":{"en":"The key slides in. Click. Light pours out…","ar":"المفتاح يدخل. كليك. ضوء يتدفق…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"CUT! Tomorrow…","ar":"توقف! غدًا…"}}]'::jsonb, array['sticker.rainbow','mimo.bow']::text[], 2, null, 'published', 1),
  ('gk-12', 'golden-key', 12, 'magic-castle', '{"en":"The Golden Door","ar":"الباب الذهبي"}'::jsonb, '{"en":"The door opens… to the whole wide world.","ar":"الباب يُفتح… على العالم الواسع كله."}'::jsonb, array['adventure','travel','greetings']::text[], '[{"speaker":"narrator","text":{"en":"But on the globe, one tiny island starts to blink… and a dragon roar echoes!","ar":"لكن على الكرة، جزيرة صغيرة تبدأ بالوميض… ويتردد زئير تنين!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Season 2 begins soon…","ar":"الموسم الثاني يبدأ قريبًا…"}}]'::jsonb, array['sticker.door','furniture.globe','mimo.sparkles']::text[], 2, 'opened-golden-door', 'published', 1),
  ('dragon-egg-01', 'dragon-egg', 1, 'magic-castle', '{"en":"The Missing Dragon Egg","ar":"بيضة التنين المفقودة"}'::jsonb, '{"en":"Mama Dragon’s egg has rolled away!","ar":"بيضة أم التنين تدحرجت بعيدًا!"}'::jsonb, array['adventure','colors','feelings']::text[], '[{"speaker":"narrator","text":{"en":"Something warm is glowing inside a cave…","ar":"شيء دافئ يتوهج داخل كهف…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.dragon']::text[], 2, null, 'published', 1),
  ('dragon-egg-02', 'dragon-egg', 2, 'magic-castle', '{"en":"The Warm Cave","ar":"الكهف الدافئ"}'::jsonb, '{"en":"The egg is in a cave — but it’s dark!","ar":"البيضة في كهف، لكنه مظلم!"}'::jsonb, array['adventure','colors','feelings']::text[], '[{"speaker":"narrator","text":{"en":"Crack… crack… the egg is hatching!","ar":"طق… طق… البيضة تفقس!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['item.lantern']::text[], 2, null, 'published', 1),
  ('dragon-egg-03', 'dragon-egg', 3, 'magic-castle', '{"en":"Hello, Little Dragon","ar":"مرحبًا أيها التنين الصغير"}'::jsonb, '{"en":"A baby dragon is born and wants to learn words!","ar":"تنين صغير وُلد ويريد تعلم الكلمات!"}'::jsonb, array['adventure','colors','feelings']::text[], null, array['mimo.hat']::text[], 2, null, 'published', 1),
  ('forest-mystery-01', 'forest-mystery', 1, 'animal-forest', '{"en":"Whispers in the Trees","ar":"همسات في الأشجار"}'::jsonb, '{"en":"The animals are whispering. Something is different in the forest.","ar":"الحيوانات تهمس. شيء مختلف في الغابة."}'::jsonb, array['animals','nature','descriptions']::text[], '[{"speaker":"narrator","text":{"en":"The river is glowing in seven colours…","ar":"النهر يتوهج بسبعة ألوان…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.rainbow']::text[], 1, null, 'published', 1),
  ('forest-mystery-02', 'forest-mystery', 2, 'animal-forest', '{"en":"The Rainbow River","ar":"نهر قوس قزح"}'::jsonb, '{"en":"Help the rainbow get back into the sky.","ar":"ساعد قوس قزح على العودة إلى السماء."}'::jsonb, array['animals','nature','descriptions']::text[], null, array['furniture.rug']::text[], 1, null, 'published', 1),
  ('forest-mystery-03', 'forest-mystery', 3, 'animal-forest', '{"en":"The Forest Party","ar":"حفلة الغابة"}'::jsonb, '{"en":"The animals throw a party to say thank you.","ar":"الحيوانات تقيم حفلة لتقول شكرًا."}'::jsonb, array['animals','nature','descriptions']::text[], null, array['furniture.plant']::text[], 1, null, 'published', 1),
  ('space-signal-01', 'space-signal', 1, 'space-world', '{"en":"The Space Signal","ar":"إشارة الفضاء"}'::jsonb, '{"en":"Beep… beep… a signal from a faraway planet!","ar":"بيب… بيب… إشارة من كوكب بعيد!"}'::jsonb, array['adventure','numbers','transport']::text[], '[{"speaker":"narrator","text":{"en":"A friendly little robot waves from the planet below…","ar":"روبوت صغير ودود يلوّح من الكوكب في الأسفل…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.rocket']::text[], 3, null, 'published', 1),
  ('space-signal-02', 'space-signal', 2, 'space-world', '{"en":"Planet Hello","ar":"كوكب مرحبًا"}'::jsonb, '{"en":"Meet Bip, a robot who only knows numbers.","ar":"تعرّف على بيب، روبوت يعرف الأرقام فقط."}'::jsonb, array['adventure','numbers','transport']::text[], '[{"speaker":"narrator","text":{"en":"The party is on the Moon… tonight!","ar":"الحفلة على القمر… الليلة!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.planet']::text[], 3, null, 'published', 1),
  ('space-signal-03', 'space-signal', 3, 'space-world', '{"en":"Moon Party","ar":"حفلة القمر"}'::jsonb, '{"en":"Dance in low gravity with new friends.","ar":"ارقص في الجاذبية المنخفضة مع أصدقاء جدد."}'::jsonb, array['adventure','numbers','transport']::text[], null, array['clothing.space']::text[], 3, null, 'published', 1),
  ('dino-map-01', 'dino-map', 1, 'dinosaur-island', '{"en":"The Dinosaur Map","ar":"خريطة الديناصورات"}'::jsonb, '{"en":"An old map shows where the dinosaurs hide their nests.","ar":"خريطة قديمة تظهر أين تخبئ الديناصورات أعشاشها."}'::jsonb, array['adventure','animals','directions']::text[], '[{"speaker":"narrator","text":{"en":"The ground shakes… STOMP… STOMP…","ar":"الأرض تهتز… دوم… دوم…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.dino']::text[], 3, null, 'published', 1),
  ('dino-map-02', 'dino-map', 2, 'dinosaur-island', '{"en":"The Gentle Giant","ar":"العملاق اللطيف"}'::jsonb, '{"en":"A huge dinosaur blocks the path — but it’s just shy.","ar":"ديناصور ضخم يسد الطريق، لكنه خجول فقط."}'::jsonb, array['adventure','animals','directions']::text[], '[{"speaker":"narrator","text":{"en":"One nest has a strange golden egg…","ar":"أحد الأعشاش فيه بيضة ذهبية غريبة…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['item.telescope']::text[], 3, null, 'published', 1),
  ('dino-map-03', 'dino-map', 3, 'dinosaur-island', '{"en":"The Nest of Wonders","ar":"عش العجائب"}'::jsonb, '{"en":"Count the eggs and keep them safe.","ar":"عدّ البيض واحفظه بأمان."}'::jsonb, array['adventure','animals','directions']::text[], null, array['mimo.scarf']::text[], 3, null, 'published', 1),
  ('castle-room-01', 'castle-room', 1, 'magic-castle', '{"en":"The Secret Castle Room","ar":"غرفة القلعة السرية"}'::jsonb, '{"en":"A painting in the castle moves its eyes…","ar":"لوحة في القلعة تحرك عينيها…"}'::jsonb, array['adventure','home','descriptions']::text[], '[{"speaker":"narrator","text":{"en":"At the top, someone is humming a song…","ar":"في الأعلى، أحدهم يدندن أغنية…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.crown']::text[], 3, null, 'published', 1),
  ('castle-room-02', 'castle-room', 2, 'magic-castle', '{"en":"The Singing Queen","ar":"الملكة المغنية"}'::jsonb, '{"en":"The queen lost her voice — help her sing again.","ar":"الملكة فقدت صوتها، ساعدها لتغني مجددًا."}'::jsonb, array['adventure','home','descriptions']::text[], null, array['clothing.cape']::text[], 3, null, 'published', 1),
  ('underwater-city-01', 'underwater-city', 1, 'underwater-world', '{"en":"Bubbles from Below","ar":"فقاعات من الأعماق"}'::jsonb, '{"en":"Strange bubbles spell out words!","ar":"فقاعات غريبة تكتب كلمات!"}'::jsonb, array['adventure','animals','colors']::text[], '[{"speaker":"narrator","text":{"en":"An octopus guards the city gate…","ar":"أخطبوط يحرس بوابة المدينة…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.shell']::text[], 3, null, 'published', 1),
  ('underwater-city-02', 'underwater-city', 2, 'underwater-world', '{"en":"The Octopus Guard","ar":"الأخطبوط الحارس"}'::jsonb, '{"en":"The octopus asks eight questions — one per arm!","ar":"الأخطبوط يسأل ثمانية أسئلة، سؤال لكل ذراع!"}'::jsonb, array['adventure','animals','colors']::text[], '[{"speaker":"narrator","text":{"en":"The city’s lights are going out…","ar":"أضواء المدينة تنطفئ…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['item.compass']::text[], 3, null, 'published', 1),
  ('underwater-city-03', 'underwater-city', 3, 'underwater-world', '{"en":"Light Up the City","ar":"أضئ المدينة"}'::jsonb, '{"en":"Use colour words to relight the coral lamps.","ar":"استخدم كلمات الألوان لتضيء مصابيح المرجان."}'::jsonb, array['adventure','animals','colors']::text[], null, array['furniture.lamp']::text[], 3, null, 'published', 1),
  ('winter-wonder-01', 'winter-wonder', 1, 'nature-mountain', '{"en":"The Snowy Surprise","ar":"مفاجأة الثلج"}'::jsonb, '{"en":"It’s snowing in LingoWorld for the very first time!","ar":"إنها تثلج في لينغو وورلد لأول مرة!"}'::jsonb, array['weather','clothing','calendar']::text[], null, array['clothing.cap']::text[], 2, null, 'published', 1),
  ('winter-wonder-02', 'winter-wonder', 2, 'nature-mountain', '{"en":"The Cosy Cabin","ar":"الكوخ الدافئ"}'::jsonb, '{"en":"Warm up with friends and stories.","ar":"تدفأ مع الأصدقاء والقصص."}'::jsonb, array['weather','clothing','calendar']::text[], null, array['furniture.sofa']::text[], 2, null, 'published', 1),
  ('first-friends-01', 'first-friends', 1, 'my-home', '{"en":"Hello, Mimo!","ar":"مرحبًا يا ميمو!"}'::jsonb, '{"en":"A magic egg wiggles. Say hello!","ar":"بيضة سحرية تتحرك. قل مرحبًا!"}'::jsonb, array['greetings','colors']::text[], '[{"speaker":"narrator","text":{"en":"The egg glows… red, blue, yellow!","ar":"البيضة تتوهج… أحمر، أزرق، أصفر!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.star']::text[], 1, null, 'published', 1),
  ('first-friends-02', 'first-friends', 2, 'my-home', '{"en":"Colour Surprise","ar":"مفاجأة الألوان"}'::jsonb, '{"en":"Find toys of every colour for Mimo.","ar":"جد ألعابًا بكل الألوان لميمو."}'::jsonb, array['colors','toys']::text[], '[{"speaker":"narrator","text":{"en":"Mimo hears a puppy outside. Woof!","ar":"ميمو يسمع جروًا في الخارج. هاو!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.rainbow']::text[], 1, null, 'published', 1),
  ('first-friends-03', 'first-friends', 3, 'playground-park', '{"en":"A Puppy at the Park","ar":"جرو في الحديقة"}'::jsonb, '{"en":"Play with a friendly puppy.","ar":"العب مع جرو لطيف."}'::jsonb, array['animals','actions']::text[], '[{"speaker":"narrator","text":{"en":"The puppy runs into the forest!","ar":"الجرو يركض إلى الغابة!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.puppy']::text[], 1, null, 'published', 1),
  ('first-friends-04', 'first-friends', 4, 'animal-forest', '{"en":"Forest Friends","ar":"أصدقاء الغابة"}'::jsonb, '{"en":"Meet the animals of the forest.","ar":"تعرّف على حيوانات الغابة."}'::jsonb, array['animals','nature']::text[], '[{"speaker":"narrator","text":{"en":"A bird sings a funny song…","ar":"طائر يغني أغنية مضحكة…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.owl']::text[], 1, null, 'published', 1),
  ('first-friends-05', 'first-friends', 5, 'music-valley', '{"en":"Bibi’s Song","ar":"أغنية بيبي"}'::jsonb, '{"en":"Count and dance with Bibi.","ar":"عُدّ وارقص مع بيبي."}'::jsonb, array['numbers','actions']::text[], '[{"speaker":"narrator","text":{"en":"Mimo is hungry… tummy rumbles!","ar":"ميمو جائع… بطنه يقرقر!"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.music']::text[], 1, null, 'published', 1),
  ('first-friends-06', 'first-friends', 6, 'supermarket-city', '{"en":"Yummy Shopping","ar":"تسوق لذيذ"}'::jsonb, '{"en":"Find Mimo’s favourite food.","ar":"جد طعام ميمو المفضل."}'::jsonb, array['food','colors']::text[], '[{"speaker":"narrator","text":{"en":"Splash! Waves at the beach…","ar":"رشرشة! أمواج على الشاطئ…"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.cookie']::text[], 1, null, 'published', 1),
  ('first-friends-07', 'first-friends', 7, 'beach-island', '{"en":"Sunny Beach","ar":"شاطئ مشمس"}'::jsonb, '{"en":"Play in the sun and sand.","ar":"العب في الشمس والرمل."}'::jsonb, array['nature','weather']::text[], '[{"speaker":"narrator","text":{"en":"Mimo yawns… time for a surprise party?","ar":"ميمو يتثاءب… حان وقت حفلة مفاجئة؟"},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.shell']::text[], 1, null, 'published', 1),
  ('first-friends-08', 'first-friends', 8, 'my-home', '{"en":"Mimo’s Party","ar":"حفلة ميمو"}'::jsonb, '{"en":"All the friends come to say hello.","ar":"كل الأصدقاء يأتون ليقولوا مرحبًا."}'::jsonb, array['family','feelings']::text[], null, array['mimo.bow']::text[], 1, null, 'published', 1),
  ('clock-01', 'clocktower-code', 1, 'school-town', '{"en":"The Stopped Clock","ar":"الساعة المتوقفة"}'::jsonb, '{"en":"Every clock in School Town stopped at 3:00. Nova needs a partner.","ar":"كل ساعات مدينة المدرسة توقفت عند الثالثة. نوفا تحتاج شريكًا."}'::jsonb, array['school','time','questions']::text[], '[{"speaker":"narrator","text":{"en":"In the library, one book is ticking.","ar":"في المكتبة، كتاب واحد يدق."},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.footprint']::text[], 1, 'joined-nova', 'published', 1),
  ('clock-02', 'clocktower-code', 2, 'school-town', '{"en":"The Ticking Book","ar":"الكتاب الذي يدق"}'::jsonb, '{"en":"A hidden code inside a library book.","ar":"شفرة مخفية داخل كتاب في المكتبة."}'::jsonb, array['school','descriptions','numbers']::text[], '[{"speaker":"narrator","text":{"en":"A shadow slips behind the fruit stand…","ar":"ظل يختبئ خلف كشك الفاكهة…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['item.compass']::text[], 1, null, 'published', 1),
  ('clock-03', 'clocktower-code', 3, 'supermarket-city', '{"en":"Undercover at the Market","ar":"متخفّون في السوق"}'::jsonb, '{"en":"Shop like a local to get the next clue.","ar":"تسوّق مثل أهل البلد لتحصل على الدليل التالي."}'::jsonb, array['shopping','food','numbers']::text[], '[{"speaker":"narrator","text":{"en":"At the park, the swings move by themselves…","ar":"في الحديقة، الأراجيح تتحرك وحدها…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.cloud']::text[], 1, null, 'published', 1),
  ('clock-04', 'clocktower-code', 4, 'playground-park', '{"en":"Directions in the Dark","ar":"اتجاهات في الظلام"}'::jsonb, '{"en":"Guide Nova through the park using only your voice.","ar":"وجّه نوفا عبر الحديقة بصوتك فقط."}'::jsonb, array['directions','actions','descriptions']::text[], '[{"speaker":"narrator","text":{"en":"The gear is stamped with an owl… Pico goes very quiet.","ar":"الترس عليه ختم بومة… بيكو يصمت تمامًا."}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['item.lantern']::text[], 2, null, 'published', 1),
  ('clock-05', 'clocktower-code', 5, 'animal-forest', '{"en":"Pico’s Secret","ar":"سر بيكو"}'::jsonb, '{"en":"Pico admits he knows who built the clocks.","ar":"بيكو يعترف أنه يعرف من صنع الساعات."}'::jsonb, array['animals','nature','feelings']::text[], '[{"speaker":"narrator","text":{"en":"On the beach, a message in a bottle — written backwards.","ar":"على الشاطئ، رسالة في زجاجة — مكتوبة بالمقلوب."}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.owl']::text[], 2, null, 'published', 1),
  ('clock-06', 'clocktower-code', 6, 'beach-island', '{"en":"The Backwards Message","ar":"الرسالة المقلوبة"}'::jsonb, '{"en":"Decode a message before the tide comes in.","ar":"فك شفرة رسالة قبل أن يأتي المد."}'::jsonb, array['weather','nature','clothing']::text[], '[{"speaker":"narrator","text":{"en":"A ticket in your name is waiting at Gate 3…","ar":"تذكرة باسمك تنتظر عند البوابة ٣…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.shell']::text[], 2, null, 'published', 1),
  ('clock-07', 'clocktower-code', 7, 'airport-adventures', '{"en":"Gate 3","ar":"البوابة ٣"}'::jsonb, '{"en":"Talk your way through the airport to meet the Clockmaker.","ar":"تحدّث لتعبر المطار وتقابل صانع الساعات."}'::jsonb, array['travel','transport','time']::text[], '[{"speaker":"narrator","text":{"en":"“You found me,” she says. “Now help me fix time itself.”","ar":"«وجدتموني»، تقول. «والآن ساعدوني لأصلح الوقت نفسه»."}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}]'::jsonb, array['sticker.cloud']::text[], 2, null, 'published', 1),
  ('clock-08', 'clocktower-code', 8, 'magic-castle', '{"en":"Fixing Time","ar":"إصلاح الوقت"}'::jsonb, '{"en":"Restart the Great Clock with everything you learned.","ar":"أعد تشغيل الساعة الكبرى بكل ما تعلمته."}'::jsonb, array['time','calendar','questions']::text[], '[{"speaker":"narrator","text":{"en":"A letter arrives with a space stamp: “Detectives needed on the Moon.”","ar":"تصل رسالة بطابع فضائي: «مطلوب محققون على القمر»."},"emotion":"surprised"},{"speaker":"narrator","text":{"en":"Next season…","ar":"الموسم القادم…"}}]'::jsonb, array['sticker.door','clothing.glasses']::text[], 2, 'solved-clocktower', 'published', 1)
insert into journey_scenes (id, journey_id, sort_order, background, lines, interaction, memory_callbacks) values
  ('gk-01.intro', 'gk-01', 0, 'my-home', '[{"speaker":"lumi","text":{"en":"Hello, {name}! I’m Lumi. I’m so happy you’re here!","ar":"مرحبًا يا {name}! أنا لومي. أنا سعيدة جدًا بوجودك!"},"emotion":"happy","target":{"phraseId":"story.hello_friend"}},{"speaker":"narrator","text":{"en":"Suddenly… something shiny falls from the sky! CLINK!","ar":"فجأة… شيء لامع يسقط من السماء! طَنْ!"},"emotion":"surprised"},{"speaker":"lumi","text":{"en":"Look! A golden key!","ar":"انظر! مفتاح ذهبي!"},"emotion":"excited","target":{"phraseId":"story.golden_key"}}]'::jsonb, null, null),
  ('gk-01.discover', 'gk-01', 1, 'my-home', '[{"speaker":"pico","text":{"en":"Hoo-hoo! Every adventure needs words. Here is our first one.","ar":"هوو هوو! كل مغامرة تحتاج كلمات. هذه أول كلمة لنا."},"emotion":"thinking","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say it with me!","ar":"قلها معي!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-01.act1', 'gk-01', 2, 'my-home', '[]'::jsonb, '{"kind":"activity","families":["listening","matching"],"purpose":{"en":"Help Lumi find things that match the key’s glow.","ar":"ساعد لومي في إيجاد أشياء تتوهج مثل المفتاح."}}'::jsonb, null),
  ('gk-01.choice', 'gk-01', 3, 'my-home', '[]'::jsonb, '{"kind":"choice","choiceKey":"gk.first-search","prompt":{"en":"Where should we look first?","ar":"أين نبحث أولًا؟"},"options":[{"id":"kitchen","emoji":"🍳","label":{"en":"The kitchen","ar":"المطبخ"}},{"id":"garden","emoji":"🌻","label":{"en":"The garden","ar":"الحديقة"}}]}'::jsonb, null),
  ('gk-01.act2', 'gk-01', 4, 'my-home', '[]'::jsonb, '{"kind":"activity","families":["speaking","movement"],"purpose":{"en":"Wake Mimo’s egg with your voice!","ar":"أيقظ بيضة ميمو بصوتك!"}}'::jsonb, null),
  ('gk-01.finale', 'gk-01', 5, 'my-home', '[{"speaker":"mimo","text":{"en":"*crack… crack…* The egg wiggles when you speak!","ar":"*طق… طق…* البيضة تتحرك عندما تتكلم!"},"emotion":"excited"},{"speaker":"lumi","text":{"en":"The key has a tiny picture of a door on it. Which door does it open?","ar":"على المفتاح صورة صغيرة لباب. أي باب يفتح؟"},"emotion":"thinking"}]'::jsonb, null, null),
  ('gk-02.intro', 'gk-02', 0, 'my-home', '[{"speaker":"zuzu","text":{"en":"Hi hi hi! I’m Zuzu! I found a clue! It’s a… banana!","ar":"مرحبا مرحبا! أنا زوزو! وجدت دليلًا! إنه… موزة!"},"emotion":"silly"},{"speaker":"lumi","text":{"en":"Zuzu, that’s your lunch! Let’s look properly.","ar":"زوزو، هذا غداؤك! لنبحث جيدًا."},"emotion":"happy"}]'::jsonb, null, '[{"choiceKey":"gk.first-search","optionId":"kitchen","line":{"speaker":"lumi","text":{"en":"Yesterday we started in the kitchen — let’s try upstairs now!","ar":"بالأمس بدأنا من المطبخ، لنجرب الطابق العلوي الآن!"}}},{"choiceKey":"gk.first-search","optionId":"garden","line":{"speaker":"lumi","text":{"en":"Yesterday you picked the garden. The key landed right there!","ar":"بالأمس اخترت الحديقة. المفتاح سقط هناك بالضبط!"}}}]'::jsonb),
  ('gk-02.discover', 'gk-02', 1, 'my-home', '[{"speaker":"pico","text":{"en":"A clue is hiding in this word!","ar":"هناك دليل مختبئ في هذه الكلمة!"},"emotion":"thinking","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Tell Zuzu the word!","ar":"قل الكلمة لزوزو!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-02.act1', 'gk-02', 2, 'my-home', '[]'::jsonb, '{"kind":"activity","families":["puzzle","listening"],"purpose":{"en":"Search the rooms for hidden clues.","ar":"ابحث في الغرف عن أدلة مخفية."}}'::jsonb, null),
  ('gk-02.act2', 'gk-02', 3, 'my-home', '[]'::jsonb, '{"kind":"activity","families":["memory","matching"],"purpose":{"en":"Match the clues to make a picture.","ar":"طابق الأدلة لتكوين صورة."}}'::jsonb, null),
  ('gk-02.finale', 'gk-02', 4, 'my-home', '[{"speaker":"nova","text":{"en":"I’m Nova. I solve mysteries. These clues are footprints… leading to the park!","ar":"أنا نوفا. أحل الألغاز. هذه الأدلة آثار أقدام… تقود إلى الحديقة العامة!"},"emotion":"thinking"}]'::jsonb, null, null),
  ('gk-03.intro', 'gk-03', 0, 'playground-park', '[{"speaker":"lumi","text":{"en":"Look at all these footprints! Let’s count them.","ar":"انظر إلى كل هذه الآثار! لنعدّها."},"emotion":"excited","target":{"phraseId":"story.look"}},{"speaker":"zuzu","text":{"en":"One, two, banana!","ar":"واحد، اثنان، موزة!"},"emotion":"silly"},{"speaker":"lumi","text":{"en":"Haha! Not banana, Zuzu. Let’s help him!","ar":"ههه! ليست موزة يا زوزو. لنساعده!"},"emotion":"happy"}]'::jsonb, null, null),
  ('gk-03.discover', 'gk-03', 1, 'playground-park', '[{"speaker":"pico","text":{"en":"The footprints stop next to this!","ar":"الآثار تتوقف بجانب هذا!"},"emotion":"surprised","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say the word to follow the trail!","ar":"قل الكلمة لتتبع الأثر!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-03.act1', 'gk-03', 2, 'playground-park', '[]'::jsonb, '{"kind":"activity","families":["movement","listening"],"purpose":{"en":"Run along the trail and catch the right words!","ar":"اركض على الأثر والتقط الكلمات الصحيحة!"}}'::jsonb, null),
  ('gk-03.choice', 'gk-03', 3, 'playground-park', '[]'::jsonb, '{"kind":"choice","choiceKey":"gk.footprints","prompt":{"en":"Two trails! Which footprints do we follow?","ar":"أثران! أي آثار نتبع؟"},"options":[{"id":"big","emoji":"🐾","label":{"en":"The big ones","ar":"الكبيرة"}},{"id":"small","emoji":"🐁","label":{"en":"The small ones","ar":"الصغيرة"}}]}'::jsonb, null),
  ('gk-03.act2', 'gk-03', 4, 'playground-park', '[]'::jsonb, '{"kind":"activity","families":["speaking","movement"],"purpose":{"en":"Tell Mimo what to do so you can climb up!","ar":"قل لميمو ماذا يفعل لتتمكن من الصعود!"}}'::jsonb, null),
  ('gk-03.finale', 'gk-03', 5, 'playground-park', '[{"speaker":"bibi","text":{"en":"Tweet-tweet! I’m Bibi! I saw who made the footprints — it was a teacher in a hurry!","ar":"تويت تويت! أنا بيبي! رأيت من صنع الآثار — كانت معلمة مستعجلة!"},"emotion":"excited"}]'::jsonb, null, null),
  ('gk-04.intro', 'gk-04', 0, 'school-town', '[{"speaker":"pico","text":{"en":"Welcome to my classroom! I found something in an old book.","ar":"أهلًا بكم في فصلي! وجدت شيئًا في كتاب قديم."},"emotion":"thinking"},{"speaker":"pico","text":{"en":"It’s a drawing of a golden door… but some colours are missing!","ar":"إنها رسمة لباب ذهبي… لكن بعض الألوان ناقصة!"},"emotion":"worried"}]'::jsonb, null, '[{"choiceKey":"gk.footprints","optionId":"big","line":{"speaker":"nova","text":{"en":"The big footprints led us here. Good choice, detective!","ar":"الآثار الكبيرة قادتنا إلى هنا. اختيار رائع أيها المحقق!"}}},{"choiceKey":"gk.footprints","optionId":"small","line":{"speaker":"nova","text":{"en":"The little footprints were a mouse! But it showed us the way here.","ar":"الآثار الصغيرة كانت لفأر! لكنه دلّنا على الطريق إلى هنا."}}}]'::jsonb),
  ('gk-04.discover', 'gk-04', 1, 'school-town', '[{"speaker":"pico","text":{"en":"First, a new word for our notebook.","ar":"أولًا، كلمة جديدة لدفترنا."},"emotion":"happy","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say it for the class!","ar":"قلها للفصل!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-04.act1', 'gk-04', 2, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["puzzle","matching"],"purpose":{"en":"Colour the missing parts of the door.","ar":"لوّن الأجزاء الناقصة من الباب."}}'::jsonb, null),
  ('gk-04.act2', 'gk-04', 3, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["listening","memory"],"purpose":{"en":"Remember the order of the colours.","ar":"تذكّر ترتيب الألوان."}}'::jsonb, null),
  ('gk-04.finale', 'gk-04', 4, 'school-town', '[{"speaker":"pico","text":{"en":"The book says: “The golden door hides behind a hundred doors…”","ar":"الكتاب يقول: «الباب الذهبي مختبئ خلف مئة باب…»"},"emotion":"surprised"},{"speaker":"zuzu","text":{"en":"A hundred doors? That’s a lot of knocking!","ar":"مئة باب؟ هذا طرق كثير!"},"emotion":"silly"}]'::jsonb, null, null),
  ('gk-05.intro', 'gk-05', 0, 'supermarket-city', '[{"speaker":"zuzu","text":{"en":"Mmm, Supermarket City! I’ll buy ten bananas and one key!","ar":"ممم، مدينة السوبرماركت! سأشتري عشر موزات ومفتاحًا!"},"emotion":"silly"},{"speaker":"lumi","text":{"en":"Look, Zuzu — that cookie has the same shape as our key!","ar":"انظر يا زوزو، تلك الكعكة لها نفس شكل مفتاحنا!"},"emotion":"surprised"}]'::jsonb, null, null),
  ('gk-05.discover', 'gk-05', 1, 'supermarket-city', '[{"speaker":"pico","text":{"en":"To talk to the baker, we need this word.","ar":"لنتحدث مع الخبّاز، نحتاج هذه الكلمة."},"emotion":"thinking","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Ask the baker!","ar":"اسأل الخبّاز!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-05.act1', 'gk-05', 2, 'supermarket-city', '[]'::jsonb, '{"kind":"activity","families":["roleplay","listening"],"purpose":{"en":"Shop for the baker’s ingredients.","ar":"تسوّق مكونات الخبّاز."}}'::jsonb, null),
  ('gk-05.act2', 'gk-05', 3, 'supermarket-city', '[]'::jsonb, '{"kind":"activity","families":["movement","matching"],"purpose":{"en":"Cook the recipe together!","ar":"اطبخوا الوصفة معًا!"}}'::jsonb, null),
  ('gk-05.finale', 'gk-05', 4, 'supermarket-city', '[{"speaker":"nova","text":{"en":"The baker says a forest owl gave her the recipe. The owl knows about the door!","ar":"الخبّازة تقول إن بومة من الغابة أعطتها الوصفة. البومة تعرف عن الباب!"},"emotion":"thinking"}]'::jsonb, null, null),
  ('gk-06.intro', 'gk-06', 0, 'animal-forest', '[{"speaker":"narrator","text":{"en":"The forest is full of sounds. Rustle… tweet… splash!","ar":"الغابة مليئة بالأصوات. حفيف… تغريد… رشرشة!"}},{"speaker":"pico","text":{"en":"That’s my cousin, the old owl! She loves riddles.","ar":"هذه قريبتي البومة العجوز! إنها تحب الألغاز."},"emotion":"happy"}]'::jsonb, null, null),
  ('gk-06.discover', 'gk-06', 1, 'animal-forest', '[{"speaker":"pico","text":{"en":"Her first riddle is about this animal.","ar":"لغزها الأول عن هذا الحيوان."},"emotion":"thinking","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Answer the owl!","ar":"أجب البومة!"},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('gk-06.act1', 'gk-06', 2, 'animal-forest', '[]'::jsonb, '{"kind":"activity","families":["listening","puzzle"],"purpose":{"en":"Listen to the animal riddles.","ar":"استمع إلى ألغاز الحيوانات."}}'::jsonb, null),
  ('gk-06.act2', 'gk-06', 3, 'animal-forest', '[]'::jsonb, '{"kind":"activity","families":["music","memory"],"purpose":{"en":"Repeat the forest song in the right order.","ar":"كرّر أغنية الغابة بالترتيب الصحيح."}}'::jsonb, null),
