insert into journey_scenes (id, journey_id, sort_order, background, lines, interaction, memory_callbacks) values
  ('clock-01.intro', 'clock-01', 0, 'school-town', '[{"speaker":"nova","text":{"en":"{name}, every clock in town stopped at exactly three o’clock. That’s not an accident.","ar":"يا {name}، كل ساعات المدينة توقفت عند الثالثة تمامًا. هذه ليست صدفة."},"emotion":"thinking"},{"speaker":"nova","text":{"en":"I keep a case notebook. Every clue gets written down — in the language we’re learning.","ar":"لدي دفتر قضايا. كل دليل يُكتب — باللغة التي نتعلمها."},"emotion":"happy"},{"speaker":"pico","text":{"en":"Detectives ask good questions. Here is our first one.","ar":"المحققون يسألون أسئلة جيدة. هذا سؤالنا الأول."},"emotion":"thinking","target":{"phraseId":"q.what_is_this"}}]'::jsonb, null, null),
  ('clock-01.discover', 'clock-01', 1, 'school-town', '[{"speaker":"nova","text":{"en":"Clue number one is written under the clock face.","ar":"الدليل الأول مكتوب تحت وجه الساعة."},"emotion":"surprised","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Read the clue aloud for the notebook.","ar":"اقرأ الدليل بصوت عالٍ للدفتر."},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('clock-01.act1', 'clock-01', 2, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["puzzle","listening"],"purpose":{"en":"Rebuild the scrambled clue.","ar":"أعد تركيب الدليل المبعثر."}}'::jsonb, null),
  ('clock-01.choice', 'clock-01', 3, 'school-town', '[]'::jsonb, '{"kind":"choice","choiceKey":"clock.first-lead","prompt":{"en":"Who do we question first?","ar":"من نستجوب أولًا؟"},"options":[{"id":"teacher","emoji":"🧑‍🏫","label":{"en":"The teacher","ar":"المعلمة"}},{"id":"baker","emoji":"🥐","label":{"en":"The baker","ar":"الخبّاز"}}]}'::jsonb, null),
  ('clock-01.act2', 'clock-01', 4, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["roleplay","speaking"],"purpose":{"en":"Ask polite questions to get information.","ar":"اطرح أسئلة مهذبة لتحصل على معلومات."}}'::jsonb, null),
  ('clock-01.finale', 'clock-01', 5, 'school-town', '[{"speaker":"nova","text":{"en":"Someone left a note: “The answer is where books sleep.”","ar":"شخص ما ترك ملاحظة: «الجواب حيث تنام الكتب»."},"emotion":"surprised"}]'::jsonb, null, null),
  ('clock-02.intro', 'clock-02', 0, 'school-town', '[{"speaker":"pico","text":{"en":"A book that ticks? Open it carefully.","ar":"كتاب يدق؟ افتحه بحذر."},"emotion":"surprised"},{"speaker":"nova","text":{"en":"Numbers! Twelve, three, seven… it’s a code.","ar":"أرقام! اثنا عشر، ثلاثة، سبعة… إنها شفرة."},"emotion":"thinking"}]'::jsonb, null, '[{"choiceKey":"clock.first-lead","optionId":"teacher","line":{"speaker":"nova","text":{"en":"The teacher told us the library was locked at three. Interesting…","ar":"المعلمة أخبرتنا أن المكتبة أُغلقت عند الثالثة. مثير…"},"emotion":"thinking"}},{"choiceKey":"clock.first-lead","optionId":"baker","line":{"speaker":"nova","text":{"en":"The baker said a stranger bought bread at three. Our first suspect!","ar":"الخبّاز قال إن غريبًا اشترى خبزًا عند الثالثة. أول مشتبه به!"},"emotion":"thinking"}}]'::jsonb),
  ('clock-02.discover', 'clock-02', 1, 'school-town', '[{"speaker":"pico","text":{"en":"The code word is…","ar":"كلمة الشفرة هي…"},"emotion":"thinking","target":{"slot":"focus1","pattern":"np"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say the code word clearly.","ar":"قل كلمة الشفرة بوضوح."},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('clock-02.act1', 'clock-02', 2, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["puzzle","matching"],"purpose":{"en":"Spell the code word letter by letter.","ar":"تهجَّ كلمة الشفرة حرفًا حرفًا."}}'::jsonb, null),
  ('clock-02.act2', 'clock-02', 3, 'school-town', '[]'::jsonb, '{"kind":"activity","families":["memory","listening"],"purpose":{"en":"Remember the number sequence.","ar":"تذكّر تسلسل الأرقام."}}'::jsonb, null),
  ('clock-02.finale', 'clock-02', 4, 'school-town', '[{"speaker":"nova","text":{"en":"The code points to the market. Someone there knows something.","ar":"الشفرة تشير إلى السوق. شخص هناك يعرف شيئًا."},"emotion":"excited"}]'::jsonb, null, null),
  ('clock-03.intro', 'clock-03', 0, 'supermarket-city', '[{"speaker":"nova","text":{"en":"We blend in. You do the talking — I’ll watch.","ar":"سنندمج. أنت تتكلم — وأنا أراقب."},"emotion":"thinking"}]'::jsonb, null, null),
  ('clock-03.discover', 'clock-03', 1, 'supermarket-city', '[{"speaker":"zuzu","text":{"en":"I’m undercover too! I’m a… pineapple.","ar":"أنا متخفٍّ أيضًا! أنا… أناناسة."},"emotion":"silly","target":{"slot":"focus1","pattern":"i-see"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Tell the shopkeeper what you see.","ar":"أخبر البائع بما تراه."},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('clock-03.act1', 'clock-03', 2, 'supermarket-city', '[]'::jsonb, '{"kind":"activity","families":["roleplay","listening"],"purpose":{"en":"Buy exactly what the clue lists.","ar":"اشترِ بالضبط ما يذكره الدليل."}}'::jsonb, null),
  ('clock-03.choice', 'clock-03', 3, 'supermarket-city', '[]'::jsonb, '{"kind":"choice","choiceKey":"clock.shadow","prompt":{"en":"The shadow drops a ticket. What do we do?","ar":"الظل يُسقط تذكرة. ماذا نفعل؟"},"options":[{"id":"follow","emoji":"👣","label":{"en":"Follow the shadow","ar":"نتبع الظل"}},{"id":"ticket","emoji":"🎫","label":{"en":"Read the ticket","ar":"نقرأ التذكرة"}}]}'::jsonb, null),
  ('clock-03.act2', 'clock-03', 4, 'supermarket-city', '[]'::jsonb, '{"kind":"activity","families":["puzzle","matching"],"purpose":{"en":"Sort the receipts to find the odd one out.","ar":"رتّب الإيصالات لتجد المختلف."}}'::jsonb, null),
  ('clock-03.finale', 'clock-03', 5, 'supermarket-city', '[{"speaker":"nova","text":{"en":"The ticket says: Playground Park, 3:00.","ar":"التذكرة تقول: حديقة الألعاب، الثالثة."},"emotion":"surprised"}]'::jsonb, null, null),
  ('clock-04.intro', 'clock-04', 0, 'playground-park', '[{"speaker":"nova","text":{"en":"It’s too dark to see. I’ll walk — you give the directions.","ar":"المكان مظلم جدًا. سأمشي — وأنت تعطي الاتجاهات."},"emotion":"worried"}]'::jsonb, null, '[{"choiceKey":"clock.shadow","optionId":"follow","line":{"speaker":"nova","text":{"en":"Good instinct following that shadow — it came this way.","ar":"حدس جيد أن تتبعنا الظل — لقد جاء من هنا."},"emotion":"thinking"}}]'::jsonb),
  ('clock-04.discover', 'clock-04', 1, 'playground-park', '[{"speaker":"pico","text":{"en":"Precise directions save time.","ar":"الاتجاهات الدقيقة توفّر الوقت."},"emotion":"thinking","target":{"slot":"focus1","pattern":"word"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say the direction word.","ar":"قل كلمة الاتجاه."},"expect":{"slot":"focus1"}}'::jsonb, null),
  ('clock-04.act1', 'clock-04', 2, 'playground-park', '[]'::jsonb, '{"kind":"activity","families":["movement","speaking"],"purpose":{"en":"Steer Nova through the maze by voice.","ar":"وجّه نوفا عبر المتاهة بصوتك."}}'::jsonb, null),
  ('clock-04.act2', 'clock-04', 3, 'playground-park', '[]'::jsonb, '{"kind":"activity","families":["listening","puzzle"],"purpose":{"en":"Find where the footprints lead.","ar":"جد إلى أين تقود الآثار."}}'::jsonb, null),
  ('clock-04.finale', 'clock-04', 4, 'playground-park', '[{"speaker":"nova","text":{"en":"Under the slide: a tiny golden gear!","ar":"تحت الزحليقة: ترس ذهبي صغير!"},"emotion":"excited"}]'::jsonb, null, null),
  ('clock-05.intro', 'clock-05', 0, 'animal-forest', '[{"speaker":"pico","text":{"en":"That owl stamp… belongs to my old teacher, the Clockmaker.","ar":"ختم البومة هذا… يخص معلمي القديم، صانع الساعات."},"emotion":"worried"},{"speaker":"nova","text":{"en":"Why didn’t you tell us?","ar":"لماذا لم تخبرنا؟"},"emotion":"surprised"}]'::jsonb, null, null),
  ('clock-05.discover', 'clock-05', 1, 'animal-forest', '[{"speaker":"pico","text":{"en":"The Clockmaker lives near this.","ar":"صانع الساعات يعيش قرب هذا."},"emotion":"thinking","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Repeat it for the notebook.","ar":"كرّرها للدفتر."},"expect":{"slot":"focus1"}}'::jsonb, null),
