  ('clock-05.act2', 'clock-05', 4, 'animal-forest', '[]'::jsonb, '{"kind":"activity","families":["matching","memory"],"purpose":{"en":"Match each animal to its tracks.","ar":"طابق كل حيوان مع آثاره."}}'::jsonb, null),
