  ('clock-06.intro', 'clock-06', 0, 'beach-island', '[{"speaker":"nova","text":{"en":"Every word is reversed. Let’s rebuild the sentences.","ar":"كل كلمة مقلوبة. لنُعِد بناء الجمل."},"emotion":"thinking"}]'::jsonb, null, '[{"choiceKey":"clock.trust","optionId":"careful","line":{"speaker":"pico","text":{"en":"I checked this clue twice — just as you asked.","ar":"تحققت من هذا الدليل مرتين — كما طلبت."},"emotion":"happy"}}]'::jsonb),
  ('clock-06.discover', 'clock-06', 1, 'beach-island', '[{"speaker":"nova","text":{"en":"The first decoded word is…","ar":"أول كلمة فككناها هي…"},"emotion":"excited","target":{"slot":"focus1","pattern":"np"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say the decoded word.","ar":"قل الكلمة المفكوكة."},"expect":{"slot":"focus1"}}'::jsonb, null),
