  ('clock-07.discover', 'clock-07', 1, 'airport-adventures', '[{"speaker":"pico","text":{"en":"At the airport you’ll need…","ar":"في المطار ستحتاج…"},"emotion":"thinking","target":{"slot":"focus1","pattern":"give-me"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Ask for it politely.","ar":"اطلبها بأدب."},"expect":{"slot":"focus1"}}'::jsonb, null),
