  ('clock-07.finale', 'clock-07', 4, 'airport-adventures', '[{"speaker":"pico","text":{"en":"There she is — the Clockmaker. She’s smiling.","ar":"ها هي — صانعة الساعات. إنها تبتسم."},"emotion":"surprised"}]'::jsonb, null, null),
  ('clock-08.intro', 'clock-08', 0, 'magic-castle', '[{"speaker":"nova","text":{"en":"The clocks stopped so someone would come looking. The Clockmaker was testing us.","ar":"توقفت الساعات كي يأتي أحد ليبحث. صانعة الساعات كانت تختبرنا."},"emotion":"thinking"}]'::jsonb, null, '[{"choiceKey":"clock.first-lead","optionId":"*","line":{"speaker":"nova","text":{"en":"Remember our very first question in School Town? It all started there.","ar":"تذكر أول سؤال لنا في مدينة المدرسة؟ كل شيء بدأ هناك."},"emotion":"happy"}}]'::jsonb),
  ('clock-08.discover', 'clock-08', 1, 'magic-castle', '[{"speaker":"pico","text":{"en":"The final gear is labelled…","ar":"الترس الأخير مكتوب عليه…"},"emotion":"excited","target":{"slot":"focus1","pattern":"this-is"}}]'::jsonb, '{"kind":"speak","prompt":{"en":"Say the final word to start the clock.","ar":"قل الكلمة الأخيرة لتشغيل الساعة."},"expect":{"slot":"focus1"}}'::jsonb, null),
