land","lines":[{"speaker":"nova","text":{"en":"“Meet me where planes sleep.” The airport!","ar":"«قابلني حيث تنام الطائرات». المطار!"},"emotion":"surprised"}]}],"cliffhanger":[{"speaker":"narrator","text":{"en":"A ticket in your name is waiting at Gate 3…","ar":"تذكرة باسمك تنتظر عند البوابة ٣…"}},{"speaker":"narrator","text":{"en":"Tomorrow…","ar":"غدًا…"}}],"rewardIds":["sticker.shell"],"minStage":2,"status":"published","version":1},{"id":"clock-07","arcId":"clocktower-code","order":7,"worldId":"airport-adventures","title":{"en":"Gate 3","ar":"البوابة ٣"},"summary":{"en":"Talk your way through the airport to meet the Clockmaker.","ar":"تحدّث لتعبر المطار وتقابل صانع الساعات."},"topics":["travel","transport","time"],"beats":[{"id":"clock-07.intro","background":"airport-adventures","lines":[{"speaker":"nova","text":{"en":"Ticket, questions, directions. Ready?","ar":"تذكرة، أسئلة، اتجاهات. جاهز؟"},"emotion":"excited"}]},{"id":"clock-07.discover","background":"airport-adventures","lines":[{"speaker":"pico","text":{"en":"At the airport you’ll need…","ar":"في المطار ستحتاج…"},"emotion":"thinking","target":{"slot":"focus1","pattern":"give-me"}}],"interaction":{"kind":"speak","prompt":{"en":"Ask for it politely.","ar":"اطلبها بأدب."},"expect":{"slot":"focus1"}}},{"id":"clock-07.act1","background":"airport-adventures","lines":[],"interaction":{"kind":"activity","families":["roleplay","speaking"],"purpose":{"en":"Check in and answer the agent.","ar":"سجّل وأجب الموظف."}}},{"id":"clock-07.act2","background":"airport-adventures","lines":[],"interaction":{"kind":"activity","families":["listening","movement"],"purpose":{"en":"Follow the announcements to Gate 3.","ar":"اتبع الإعلانات إلى البوابة ٣."}}},{"id":"clock-07.finale","background":"airport-adventures","lines":[{"speaker":"pico","text":{"en":"There she is — the Clockmaker. She’s smiling.","ar":"ها هي — صانعة الساعات. إنها تبتسم."},"emotion":"surprised"}]}],"cliffhanger":[{"speaker":"narrator","text":{"en":"“You found me,”